// "Login with Google" — Google OAuth 2.0 / OpenID Connect.
//
// Plain server-side module (NO "use server") — imported only by the two Google
// auth route handlers under app/api/auth/google. Never bundled to the client;
// no client secret or token is ever logged or returned to the browser.
//
// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
// Authorization Code flow with a client secret (client_secret_post). Google is
// the identity provider; we only ever ask for the user's identity, never any
// Google API scope beyond `openid email profile`.
//
// ---------------------------------------------------------------------------
// PROTOCOL CONSTANTS — Google's OIDC endpoints (stable, from
// https://accounts.google.com/.well-known/openid-configuration):
//   * authorize  https://accounts.google.com/o/oauth2/v2/auth
//   * token      https://oauth2.googleapis.com/token
//   * userinfo   https://openidconnect.googleapis.com/v1/userinfo
// ---------------------------------------------------------------------------

import { randomBytes } from "node:crypto";

export const GOOGLE_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
export const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";
export const GOOGLE_USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";

/** The scopes we request: identity only. */
export const GOOGLE_OAUTH_SCOPES = "openid email profile";

/** Random URL-safe string for the CSRF `state`. */
export function randomUrlSafe(bytes = 32): string {
  return randomBytes(bytes).toString("base64url");
}

/**
 * Redirect URI — must be registered verbatim on the Google OAuth client.
 * `${APP_URL}/api/auth/google/callback`.
 */
export function googleRedirectUri(): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  return `${base}/api/auth/google/callback`;
}

/**
 * Is the OAuth client configured in this environment? When false the login page
 * HIDES the "Continue with Google" button, so nothing shows a broken flow before
 * the operator adds the credentials. Read at request time (not module top-level)
 * so an unset value never crashes boot.
 */
export function googleOauthConfigured(): boolean {
  return Boolean(
    (process.env.GOOGLE_CLIENT_ID ?? "").trim() &&
      (process.env.GOOGLE_CLIENT_SECRET ?? "").trim(),
  );
}

/** Build the Google consent URL for this sign-in attempt. */
export function googleAuthorizeUrl(opts: { state: string }): string {
  const url = new URL(GOOGLE_AUTHORIZE_URL);
  url.searchParams.set("client_id", (process.env.GOOGLE_CLIENT_ID ?? "").trim());
  url.searchParams.set("redirect_uri", googleRedirectUri());
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", GOOGLE_OAUTH_SCOPES);
  url.searchParams.set("state", opts.state);
  // We do not need offline access (no Google API calls after sign-in), so ask
  // for an online-only grant and always let the user pick the account.
  url.searchParams.set("access_type", "online");
  url.searchParams.set("prompt", "select_account");
  return url.toString();
}

// ---- Token endpoint --------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  id_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
  error?: string;
  error_description?: string;
};

/**
 * Exchange an authorization `code` for tokens (client_secret_post). Returns the
 * access token or a short, safe error string — NEVER the client secret or any
 * token in the error text.
 */
export async function googleExchangeCode(
  code: string,
): Promise<{ accessToken?: string; error?: string }> {
  const clientId = (process.env.GOOGLE_CLIENT_ID ?? "").trim();
  const clientSecret = (process.env.GOOGLE_CLIENT_SECRET ?? "").trim();

  const params = new URLSearchParams({
    code,
    client_id: clientId,
    client_secret: clientSecret,
    redirect_uri: googleRedirectUri(),
    grant_type: "authorization_code",
  });

  let res: Response;
  try {
    res = await fetch(GOOGLE_TOKEN_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: params.toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to finish signing in. Try again shortly." };
  }

  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Google rejected the sign-in (${String(detail).slice(0, 160)}).` };
  }

  return { accessToken: parsed.access_token };
}

// ---- Userinfo --------------------------------------------------------------

export type GoogleProfile = {
  sub: string;
  email: string;
  emailVerified: boolean;
  name: string;
  picture: string | null;
};

type UserinfoResponse = {
  sub?: string;
  email?: string;
  email_verified?: boolean | string;
  name?: string;
  given_name?: string;
  picture?: string;
};

/**
 * Fetch the signed-in user's profile from the OIDC userinfo endpoint with the
 * bearer access token. Returns the normalised profile or a safe error string.
 * `emailVerified` normalises Google's boolean-or-"true"-string form.
 */
export async function googleFetchProfile(
  accessToken: string,
): Promise<{ profile?: GoogleProfile; error?: string }> {
  let res: Response;
  try {
    res = await fetch(GOOGLE_USERINFO_URL, {
      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to read your profile. Try again shortly." };
  }

  let parsed: UserinfoResponse | null = null;
  try {
    parsed = (await res.json()) as UserinfoResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.sub || !parsed?.email) {
    return { error: "Google didn't return your profile. Please try again." };
  }

  const emailVerified = parsed.email_verified === true || parsed.email_verified === "true";
  return {
    profile: {
      sub: parsed.sub,
      email: parsed.email,
      emailVerified,
      name: (parsed.name ?? parsed.given_name ?? parsed.email.split("@")[0] ?? "").trim(),
      picture: parsed.picture ?? null,
    },
  };
}

